import {
    BooleanColumn,
    FieldNameColumn,
    GenericColumn,
    StringColumn,
    Table,
    TableNameColumn,
    TranslatedTextColumn,
} from '../../db'

export const sys_relationship = Table({
    name: 'sys_relationship',
    extends: 'sys_metadata',
    schema: {
        advanced: BooleanColumn({
            mandatory: false,
            label: 'Advanced',
            read_only: false,
            active: true,
            default: false,
        }),
        apply_to: GenericColumn({
            mandatory: false,
            label: 'Apply to',
            read_only: false,
            active: true,
            column_type: 'script_plain',
        }),
        basic_apply_to: TableNameColumn({
            mandatory: false,
            label: 'Applies to table',
            read_only: false,
            active: true,
        }),
        basic_query_from: TableNameColumn({
            mandatory: false,
            label: 'Queries from table',
            read_only: false,
            active: true,
        }),
        insert_callback: GenericColumn({
            mandatory: false,
            label: 'Insert callback',
            read_only: false,
            active: true,
            column_type: 'script_plain',
        }),
        name: TranslatedTextColumn({ mandatory: false, label: 'Name', read_only: false, active: true }),
        query_from: GenericColumn({
            mandatory: false,
            label: 'Query from',
            read_only: false,
            active: true,
            column_type: 'script_plain',
        }),
        query_with: GenericColumn({
            mandatory: false,
            label: 'Query with',
            read_only: false,
            active: true,
            default:
                '(function refineQuery(current, parent) {\n\n\t// Add your code here, such as current.addQuery(field, value);\n\n})(current, parent);',
            column_type: 'script_plain',
        }),
        reference_field: FieldNameColumn({
            mandatory: false,
            label: 'Reference field',
            read_only: false,
            active: true,
        }),
        related_list: StringColumn({
            mandatory: false,
            label: 'Related list',
            read_only: true,
            active: true,
            maxLength: 32,
            dropdown: 'none',
        }),
        simple_reference: BooleanColumn({
            mandatory: false,
            label: 'Simple reference',
            read_only: false,
            active: true,
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
    },
})
